def run(_context):
    import adsk.core, adsk.cam
    camMgr = adsk.cam.CAMManager.get()
    libs = camMgr.libraryManager.toolLibraries
    locs = [adsk.cam.LibraryLocations.LocalLibraryLocation,
            adsk.cam.LibraryLocations.Fusion360LibraryLocation,
            adsk.cam.LibraryLocations.CloudLibraryLocation]
    for loc in locs:
        try:
            urls = libs.urlByLocation(loc)
            def walk(url, depth=0):
                for cu in libs.childAssetURLs(url):
                    s = cu.leafName
                    print("  "*depth + s, "|", cu.toString())
                    if 'TIW' in s or 'tiw' in s.lower():
                        lib = libs.toolLibraryAtURL(cu)
                        for t in lib:
                            tp = t.parameters
                            try:
                                d = tp.itemByName('tool_diameter').value.value*10
                            except: d=0
                            print("     TOOL", t.parameters.itemByName('tool_number').value.value if tp.itemByName('tool_number') else '?',
                                  t.parameters.itemByName('tool_type').value.value, "D=%.2f"%d,
                                  t.description)
                    walk(cu, depth+1)
            walk(urls)
        except Exception as e:
            print("loc err", e)

