    import adsk.cam
    camMgr = adsk.cam.CAMManager.get()
    libs = camMgr.libraryManager.toolLibraries
    url = libs.urlByLocation(adsk.cam.LibraryLocations.LocalLibraryLocation)
    for cu in libs.childAssetURLs(url):
        if 'TIW' in cu.leafName:
            liburl = cu; break
    lib = libs.toolLibraryAtURL(liburl)
    # find indices for tools 21,3,9,46 in library iteration order
    want = {21:None,3:None,9:None,46:None,11:None}
    for i,t in enumerate(lib):
        n=t.parameters.itemByName('tool_number').value.value
        if n in want and want[n] is None:
            want[n]=i
    print("lib indices:", want)
    added={}
    for tn,idx in want.items():
        res = mb.add_tool(liburl.toString(), idx)
        print("added T%d ->"%tn, res)
        added[tn]=res
    return str(added)

